-- MUSEHRAshared backend schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','admin','staff');
create type public.order_status as enum ('pending','confirmed','processing','shipped','delivered','cancelled','returned');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role public.app_role not null default 'customer', created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text, image_url text, is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, category_id uuid references public.categories(id), price numeric(12,2) not null check(price>=0), compare_at_price numeric(12,2) check(compare_at_price is null or compare_at_price>=price), images text[] not null default '{}', tags text[] not null default '{}', is_featured boolean not null default false, status text not null default 'draft' check(status in ('draft','published','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, sku text unique, size text not null, color_name text not null default 'Default', color_hex text, stock_quantity int not null default 0 check(stock_quantity>=0), low_stock_threshold int not null default 3, is_active boolean not null default true, unique(product_id,size,color_name));
create table public.inventory_logs (id uuid primary key default gen_random_uuid(), variant_id uuid not null references public.product_variants(id), change_quantity int not null, previous_quantity int not null, new_quantity int not null, reason text not null, changed_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, recipient_name text not null, phone text not null, line1 text not null, line2 text, city text not null, postal_code text, is_default boolean not null default false, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text not null unique default ('AUR-'||upper(substr(encode(gen_random_bytes(6),'hex'),1,10))), user_id uuid references auth.users(id), customer_name text not null, email text not null, phone text not null, shipping_address jsonb not null, status public.order_status not null default 'pending', payment_method text not null default 'cod', payment_status text not null default 'unpaid', subtotal numeric(12,2) not null, delivery_fee numeric(12,2) not null default 0, discount_total numeric(12,2) not null default 0, total numeric(12,2) not null, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), variant_id uuid references public.product_variants(id), product_name text not null, size text, color_name text, unit_price numeric(12,2) not null, quantity int not null check(quantity>0), line_total numeric(12,2) not null);
create table public.reviews (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, order_item_id uuid references public.order_items(id), rating int not null check(rating between 1 and 5), title text, body text, is_verified_purchase boolean not null default false, is_published boolean not null default false, created_at timestamptz not null default now(), unique(product_id,user_id,order_item_id));
create table public.wishlists (user_id uuid not null references auth.users(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,product_id));
create table public.coupons (id uuid primary key default gen_random_uuid(), code text not null unique, discount_type text not null check(discount_type in ('percentage','fixed')), discount_value numeric(12,2) not null, minimum_order numeric(12,2) not null default 0, starts_at timestamptz, expires_at timestamptz, usage_limit int, used_count int not null default 0, is_active boolean not null default true);
create table public.store_settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('admin','staff')); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Admin inventory adjustment. Called by both web admin and future React Native app through authenticated RPC.
create or replace function public.adjust_inventory(p_variant_id uuid,p_delta int,p_reason text) returns public.product_variants language plpgsql security definer set search_path=public as $$ declare v public.product_variants; old_qty int; begin if not public.is_admin() then raise exception 'Admin access required'; end if; select * into v from public.product_variants where id=p_variant_id for update; if not found then raise exception 'Variant not found'; end if; old_qty:=v.stock_quantity; if old_qty+p_delta<0 then raise exception 'Insufficient stock'; end if; update public.product_variants set stock_quantity=old_qty+p_delta where id=p_variant_id returning * into v; insert into public.inventory_logs(variant_id,change_quantity,previous_quantity,new_quantity,reason,changed_by) values(p_variant_id,p_delta,old_qty,v.stock_quantity,p_reason,auth.uid()); return v; end; $$;
-- Atomic order placement: validate and decrement every variant under row locks.
create or replace function public.place_order(p_customer_name text,p_email text,p_phone text,p_shipping_address jsonb,p_items jsonb,p_payment_method text default 'cod',p_delivery_fee numeric default 0,p_notes text default null) returns public.orders language plpgsql security definer set search_path=public as $$ declare item jsonb; v public.product_variants; prod public.products; new_order public.orders; sub numeric(12,2):=0; line numeric(12,2); q int; begin if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Order must contain items'; end if; for item in select * from jsonb_array_elements(p_items) loop q:=(item->>'quantity')::int; if q<1 then raise exception 'Invalid quantity'; end if; select * into v from public.product_variants where id=(item->>'variant_id')::uuid and is_active=true for update; if not found or v.stock_quantity<q then raise exception 'One or more items are unavailable'; end if; select * into prod from public.products where id=v.product_id and status='published'; if not found then raise exception 'Product unavailable'; end if; line:=prod.price*q; sub:=sub+line; end loop; insert into public.orders(user_id,customer_name,email,phone,shipping_address,payment_method,subtotal,delivery_fee,total,notes) values(auth.uid(),p_customer_name,p_email,p_phone,p_shipping_address,p_payment_method,sub,p_delivery_fee,sub+p_delivery_fee,p_notes) returning * into new_order; for item in select * from jsonb_array_elements(p_items) loop q:=(item->>'quantity')::int; select * into v from public.product_variants where id=(item->>'variant_id')::uuid for update; select * into prod from public.products where id=v.product_id; line:=prod.price*q; update public.product_variants set stock_quantity=stock_quantity-q where id=v.id; insert into public.order_items(order_id,product_id,variant_id,product_name,size,color_name,unit_price,quantity,line_total) values(new_order.id,prod.id,v.id,prod.name,v.size,v.color_name,prod.price,q,line); insert into public.inventory_logs(variant_id,change_quantity,previous_quantity,new_quantity,reason,changed_by) values(v.id,-q,v.stock_quantity,v.stock_quantity-q,'Customer order '||new_order.order_number,auth.uid()); end loop; return new_order; end; $$;
-- Enable RLS on all business tables.
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_variants enable row level security; alter table public.inventory_logs enable row level security; alter table public.addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.reviews enable row level security; alter table public.wishlists enable row level security; alter table public.coupons enable row level security; alter table public.store_settings enable row level security;
create policy "profiles own or admin read" on public.profiles for select using(id=auth.uid() or public.is_admin()); create policy "profiles own update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "public active categories" on public.categories for select using(is_active or public.is_admin()); create policy "admin categories manage" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "public published products" on public.products for select using(status='published' or public.is_admin()); create policy "admin products manage" on public.products for all using(public.is_admin()) with check(public.is_admin());
create policy "public active variants" on public.product_variants for select using(is_active or public.is_admin()); create policy "admin variants manage" on public.product_variants for all using(public.is_admin()) with check(public.is_admin());
create policy "admin inventory logs" on public.inventory_logs for select using(public.is_admin()); create policy "address owner" on public.addresses for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "customer own orders admin all" on public.orders for select using(user_id=auth.uid() or public.is_admin()); create policy "customer own order items admin all" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_admin())));
create policy "admin update orders" on public.orders for update using(public.is_admin()) with check(public.is_admin());
create policy "published reviews readable" on public.reviews for select using(is_published or user_id=auth.uid() or public.is_admin()); create policy "customer create own reviews" on public.reviews for insert with check(user_id=auth.uid()); create policy "admin moderate reviews" on public.reviews for update using(public.is_admin()) with check(public.is_admin());
create policy "wishlist owner" on public.wishlists for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "active coupons readable" on public.coupons for select using(is_active or public.is_admin()); create policy "admin coupons manage" on public.coupons for all using(public.is_admin()) with check(public.is_admin()); create policy "store settings public read" on public.store_settings for select using(true); create policy "admin settings manage" on public.store_settings for all using(public.is_admin()) with check(public.is_admin());
-- Storage: create bucket product-images in dashboard, then apply these policies.
insert into storage.buckets(id,name,public) values('product-images','product-images',true) on conflict(id) do nothing;
create policy "public read product images" on storage.objects for select using(bucket_id='product-images'); create policy "admin upload product images" on storage.objects for insert with check(bucket_id='product-images' and public.is_admin()); create policy "admin update product images" on storage.objects for update using(bucket_id='product-images' and public.is_admin()); create policy "admin delete product images" on storage.objects for delete using(bucket_id='product-images' and public.is_admin());
